package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.IdTokenEncryptedResponseEncVO;

class IdTokenEncryptedResponseEncValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of id token encrypted response enc of oauth client")
  void test_id_token_encrypted_response_enc_value_holder_assign_plain_value() {
    Object holder = new Object();
    IdTokenEncryptedResponseEncValueHolder<Object> value =
        new IdTokenEncryptedResponseEncValueHolder<>(holder);
    Assertions.assertSame(holder, value.idTokenEncryptedResponseEnc("one"),
        "Setters must return the holder");
    Assertions.assertTrue(value.getIdTokenEncryptedResponseEncValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getIdTokenEncryptedResponseEnc().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.idTokenEncryptedResponseEncNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getIdTokenEncryptedResponseEncValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getIdTokenEncryptedResponseEnc().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of id token encrypted response enc of oauth client")
  void test_id_token_encrypted_response_enc_value_holder_assign_value_object() {
    Object holder = new Object();
    IdTokenEncryptedResponseEncValueHolder<Object> value =
        new IdTokenEncryptedResponseEncValueHolder<>(holder);
    IdTokenEncryptedResponseEncVO vo = IdTokenEncryptedResponseEncVO.from("one");
    Assertions.assertFalse(value.getIdTokenEncryptedResponseEncValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.idTokenEncryptedResponseEnc(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getIdTokenEncryptedResponseEncValue().orElseThrow());
    Assertions.assertSame(holder, value.idTokenEncryptedResponseEnc(Optional.empty()));
    Assertions.assertFalse(value.getIdTokenEncryptedResponseEncValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.idTokenEncryptedResponseEnc(Optional.of(vo)));
    Assertions.assertSame(vo, value.getIdTokenEncryptedResponseEncValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of id token encrypted response enc of oauth client against the original")
  void test_id_token_encrypted_response_enc_value_holder_read() {
    Object holder = new Object();
    IdTokenEncryptedResponseEncValueHolder<Object> value =
        new IdTokenEncryptedResponseEncValueHolder<>(holder);
    IdTokenEncryptedResponseEncVO vo = IdTokenEncryptedResponseEncVO.from("one");
    IdTokenEncryptedResponseEncVO other = IdTokenEncryptedResponseEncVO.from("one");
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getIdTokenEncryptedResponseEncValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other,
        value.readIdTokenEncryptedResponseEnc(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readIdTokenEncryptedResponseEnc(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.idTokenEncryptedResponseEnc(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readIdTokenEncryptedResponseEnc(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readIdTokenEncryptedResponseEnc(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of id token encrypted response enc of oauth client")
  void test_id_token_encrypted_response_enc_value_holder_unset() {
    Object holder = new Object();
    IdTokenEncryptedResponseEncValueHolder<Object> value =
        new IdTokenEncryptedResponseEncValueHolder<>(holder);
    IdTokenEncryptedResponseEncVO vo = IdTokenEncryptedResponseEncVO.from("one");
    value.idTokenEncryptedResponseEnc(vo);
    Assertions.assertSame(holder,
        value.unsetIdTokenEncryptedResponseEncIfMatches("idTokenEncryptedResponseEnc_other"));
    Assertions.assertTrue(value.getIdTokenEncryptedResponseEncValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetIdTokenEncryptedResponseEncIfMatches("idTokenEncryptedResponseEnc"));
    Assertions.assertFalse(value.getIdTokenEncryptedResponseEncValue().isPresent(),
        "The field name must clear the value");
    value.idTokenEncryptedResponseEnc(vo);
    Assertions.assertSame(holder, value.unsetIdTokenEncryptedResponseEnc());
    Assertions.assertFalse(value.getIdTokenEncryptedResponseEncValue().isPresent(),
        "Unset must clear the value");
  }
}
